# Generate the full flat list for submission

def vector_to_int(v):
    return v[0] + 2*v[1] + 4*v[2] + 8*v[3] - 1

def int_to_vector(i):
    n = i + 1
    return ((n >> 0) & 1, (n >> 1) & 1, (n >> 2) & 1, (n >> 3) & 1)

def xor_vec(u, v):
    return tuple((u[i] ^ v[i]) for i in range(4))

vectors = [int_to_vector(i) for i in range(15)]

# Generate all lines (triples) of PG(3,2)
lines = []
for i in range(15):
    for j in range(i+1, 15):
        u = vectors[i]
        v = vectors[j]
        w = xor_vec(u, v)
        k = vector_to_int(w)
        if k > j:
            lines.append((i, j, k))

# Duplicate each line to get 70 blocks
blocks = lines + lines

# Build incidence matrix: 15 rows x 70 columns
v = 15
b = 70
matrix = [[0]*b for _ in range(v)]
for col, triple in enumerate(blocks):
    for p in triple:
        matrix[p][col] = 1

# Flatten
flat = []
for row in matrix:
    flat.extend(row)

print("Flat list:")
print(flat)
print(f"Length: {len(flat)}")
